"""Transparent author QA fixtures for P04–P06. Not learner hidden grading.

Run: python tests/test_p04_p06_reference.py
"""
import copy
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
SOLUTIONS=json.loads(r'''{"P04-G01":{"apply":"metadata = {specimen_id: {'channel':channel,'fields':fields}}\nfield_count = metadata[specimen_id]['fields']","prove":"sample_record = {sample: {'stain':stain,'replicate':replicate}}\nreplicate_id = sample_record[sample]['replicate']"},"P04-G02":{"apply":"meta = records.get(sample_id,{}).get('analysis',{})\nmean_focus = meta.get('focus')\nhas_focus = mean_focus is not None","prove":"meta = batch_data.get(batch_id,{}).get('environment',{})\ntemperature = meta.get('temperature')\nrecorded = temperature is not None"},"P04-G03":{"apply":"seen = set()\nrepeats = set()\nunique_ids = []\nduplicate_ids = []\nfor value in ids:\n    if value not in seen:\n        seen.add(value)\n        unique_ids.append(value)\n    elif value not in repeats:\n        repeats.add(value)\n        duplicate_ids.append(value)\nunique_count = len(unique_ids)","prove":"seen = set()\nkept=[]\nexcluded_seen=[]\nblocked = set(excluded_ids)\nfor sid in sample_ids:\n    if sid in seen:\n        continue\n    seen.add(sid)\n    if sid in blocked:\n        excluded_seen.append(sid)\n    else:\n        kept.append(sid)"},"P04-G04":{"apply":"passing_ids = [sid for sid,score in field_pairs if score is not None and 0 <= score <= 1 and score >= minimum]","prove":"selected_names = [name for name,count in observations if count is not None and count >= 0 and count >= min_count]"},"P04-G05":{"apply":"accepted=[]\nfield_total=0\nfor sid,meta in records.items():\n    if meta.get('valid') is True and isinstance(meta.get('fields'),int) and meta['fields']>0:\n        accepted.append(sid)\n        field_total += meta['fields']","prove":"selected_ids=[]\nfor sid,meta in channels.items():\n    if meta.get('marker') == target_marker and meta.get('qc') is True:\n        selected_ids.append(sid)\nselected_count=len(selected_ids)"},"P04-G06":{"apply":"length_ok = len(ids)==len(scores)\npaired=list(zip(ids,scores)) if length_ok else []\nmissing_ids=[sid for sid,score in paired if score is None]","prove":"aligned = len(field_names)==len(counts)\nsummary = dict(zip(field_names,counts)) if aligned else {}\ncount_total = sum(counts) if aligned else 0"},"P04-CAPSTONE":{"apply":"by_id={}\nduplicate_ids=[]\nincomplete_ids=[]\nseen_repeats=set()\nfor rec in records:\n    sid=rec['id']\n    if sid in by_id:\n        if sid not in seen_repeats:\n            duplicate_ids.append(sid)\n            seen_repeats.add(sid)\n        continue\n    by_id[sid]=rec.copy()\n    if not rec.get('channel') or rec.get('fields') is None:\n        incomplete_ids.append(sid)\nreport=f'stored={len(by_id)}; duplicates={len(duplicate_ids)}; incomplete={len(incomplete_ids)}'\nprint(report)","prove":"selected={}\nduplicate_keys=[]\nmissing_keys=[]\nseen=set()\nrepeated=set()\nfor sid,meta in samples:\n    if sid in seen:\n        if sid not in repeated:\n            duplicate_keys.append(sid)\n            repeated.add(sid)\n        continue\n    seen.add(sid)\n    if not meta.get('marker') or not meta.get('batch') or meta.get('count') is None:\n        missing_keys.append(sid)\n    elif meta['marker']==required_marker:\n        selected[sid]=meta.copy()\nreport_line=f'selected={len(selected)} | duplicates={len(duplicate_keys)} | missing={len(missing_keys)}'\nprint(report_line)"},"P04-REVIEW":{"prove":"kept=[]\nrepeated=[]\nunknown=[]\nseen=set()\nrepeats=set()\nallowed=set(allowed_channels)\nfor sid,channel in acquisitions:\n    if sid in seen:\n        if sid not in repeats:\n            repeated.append(sid)\n            repeats.add(sid)\n        continue\n    seen.add(sid)\n    if channel in allowed:\n        kept.append(sid)\n    else:\n        unknown.append(sid)\nline=f'kept={len(kept)}; repeated={len(repeated)}; unknown={len(unknown)}'\nprint(line)"},"P05-G01":{"apply":"def to_um(pixels, px_per_um):\n    return pixels / px_per_um\nwidth_um = to_um(pixels, px_per_um)","prove":"def speed_um_per_min(displacement_px,calibration_px_per_um,interval_min):\n    return displacement_px / calibration_px_per_um / interval_min\nspeed=speed_um_per_min(displacement_px,calibration_px_per_um,interval_min)"},"P05-G02":{"apply":"def describe_field(field_id,channel='GFP'):\n    return f'{field_id} | {channel}'\nlabel=describe_field(field_id,channel)","prove":"def passes_focus(score,minimum=0.8):\n    return score is not None and 0<=score<=1 and score>=minimum\naccepted=passes_focus(focus_score,threshold)"},"P05-G03":{"apply":"def keep_scores(scores,minimum):\n    return [x for x in scores if x is not None and 0<=x<=1 and x>=minimum]\nselected=keep_scores(scores,minimum)","prove":"def scaled_counts(counts,factor):\n    return [value*factor for value in counts]\nscaled=scaled_counts(counts,factor)"},"P05-G04":{"apply":"def specimen_label(sample_id: str,fields: int)->str:\n    \"\"\"Return a specimen label and its recorded number of fields.\"\"\"\n    return f'{sample_id}: {fields} fields'\nsummary=specimen_label(sample_id,fields)","prove":"def mean_or_none(values: list)->float|None:\n    \"\"\"Return the arithmetic mean or None if there are no observations.\"\"\"\n    return sum(values)/len(values) if values else None\nresult=mean_or_none(values)"},"P05-G05":{"apply":"def convert_width(pixels,scale):\n    if scale<=0:\n        raise ValueError('scale must be positive')\n    return pixels/scale\ndef safe_width(pixels,scale):\n    try:\n        return {'ok':True,'value':convert_width(pixels,scale)}\n    except ValueError:\n        return {'ok':False,'value':None}\nresult=safe_width(pixels,scale)","prove":"def read_quality(score):\n    if score is None or not 0<=score<=1:\n        raise ValueError('invalid quality')\n    return score\ndef quality_report(score):\n    try:\n        read_quality(score)\n        return 'VALID'\n    except ValueError:\n        return 'INVALID'\nstatus=quality_report(focus_score)"},"P05-G06":{"apply":"import math\ndef circle_area_um2(radius_um):\n    return math.pi*radius_um**2 if radius_um>=0 else None\narea_um2=circle_area_um2(radius_um)","prove":"import statistics\ndef mean_focus(scores):\n    valid=[x for x in scores if x is not None]\n    return statistics.mean(valid) if valid else None\nmean_score=mean_focus(scores)"},"P05-CAPSTONE":{"apply":"def evaluate_fields(records,minimum_um):\n    \"\"\"Audit measured field widths without mutating source records.\"\"\"\n    result={'kept':[],'low':[],'invalid':[]}\n    for sid,pixels,scale in records:\n        if pixels is None or scale<=0:\n            result['invalid'].append(sid)\n        elif pixels/scale >= minimum_um:\n            result['kept'].append(sid)\n        else:\n            result['low'].append(sid)\n    return result\naudit=evaluate_fields(records,minimum_um)\nprint(f\"kept={len(audit['kept'])}; low={len(audit['low'])}; invalid={len(audit['invalid'])}\")","prove":"def audit_widths(readings,ceiling_um):\n    \"\"\"Classify unfamiliar field ordering and an inclusive maximum.\"\"\"\n    result={'within':[],'above':[],'invalid':[]}\n    for pixels,tag,scale in readings:\n        if pixels is None or scale<=0:\n            result['invalid'].append(tag)\n        elif pixels/scale<=ceiling_um:\n            result['within'].append(tag)\n        else:\n            result['above'].append(tag)\n    return result\nresult=audit_widths(readings,ceiling_um)\nprint(f\"within={len(result['within'])} | above={len(result['above'])} | invalid={len(result['invalid'])}\")"},"P05-REVIEW":{"prove":"def summarize_measurements(values,scale):\n    \"\"\"Summarize valid measured widths with an explicit empty policy.\"\"\"\n    if scale<=0:\n        return {'n':0,'mean_um':None}\n    valid=[x/scale for x in values if x is not None]\n    return {'n':len(valid),'mean_um':sum(valid)/len(valid) if valid else None}\nsummary=summarize_measurements(values,scale)\nprint(f\"n={summary['n']} | mean={summary['mean_um']}\")"},"P06-G01":{"apply":"from pathlib import Path\nimport tempfile\nwith tempfile.TemporaryDirectory() as folder:\n    path=Path(folder)/'fields.txt'\n    path.write_text('\\n'.join(field_ids),encoding='utf-8')\n    recovered_ids=path.read_text(encoding='utf-8').splitlines()\ntotal_ids=len(recovered_ids)","prove":"from pathlib import Path\nimport tempfile\nwith tempfile.TemporaryDirectory() as folder:\n    path=Path(folder)/'observations.txt'\n    path.write_text('\\n'.join(f'{sid},{channel}' for sid,channel in observations),encoding='utf-8')\n    recovered_rows=[line.split(',',1) for line in path.read_text(encoding='utf-8').splitlines()]\nrow_count=len(recovered_rows)"},"P06-G02":{"apply":"commands=[f'{python_cmd} -m venv .venv','source .venv/bin/activate','python -m pip install -r requirements.txt']\nexecuted_locally=False","prove":"activate_command='.'+chr(92)+'.venv'+chr(92)+'Scripts'+chr(92)+'Activate.ps1' if target_os=='windows' else 'source .venv/bin/activate'\nverification='NOT_RUN_LOCALLY'"},"P06-G03":{"apply":"import json\nrecord={'id':sample_id,'fields':field_count,'channel':channel}\njson_text=json.dumps(record,sort_keys=True)\nrestored=json.loads(json_text)","prove":"import json\nspecimen={'sample':sample,'focus':focus,'passed':passed}\npayload=json.dumps(specimen,sort_keys=True)\nroundtrip=json.loads(payload)"},"P06-G04":{"apply":"def width_um(pixels,scale):\n    return pixels/scale\ndef test_width(fn):\n    try:\n        assert fn(20,4)==5\n        assert fn(0,4)==0\n        return True\n    except AssertionError:\n        return False\npassed=test_width(width_um)","prove":"def mean_or_none(values):\n    return sum(values)/len(values) if values else None\ndef test_mean(fn):\n    try:\n        assert fn([2,4])==3\n        assert fn([]) is None\n        return True\n    except AssertionError:\n        return False\ngood_test=test_mean(mean_or_none)\nbroken_detected=(test_mean(lambda x:0) is False)"},"P06-G05":{"apply":"def convert_field(pixels,scale):\n    return pixels/scale if pixels is not None and scale>0 else None\ndef process_fields(rows,scale):\n    return [[sid,convert_field(pixels,scale)] for sid,pixels in rows]\nprocessed=process_fields(rows,px_per_um)","prove":"def summarize_batch(rows,scale):\n    if scale<=0:\n        return {'observed':0,'missing':len(rows),'mean_um':None}\n    valid=[pixels/scale for pixels,tag in rows if pixels is not None]\n    return {'observed':len(valid),'missing':len(rows)-len(valid),'mean_um':sum(valid)/len(valid) if valid else None}\nsummary=summarize_batch(rows,scale)"},"P06-G06":{"apply":"commands=['git status',f'git add {script_name}',f'git commit -m \"{message}\"']\ngit_executed=False","prove":"next_steps=[f'git diff -- {changed_file}',f'git add {changed_file}',f'git commit -m \"{commit_message}\"','git status']\nevidence='NOT_VERIFIED_LOCALLY'"},"P06-CAPSTONE":{"apply":"import json\ndef build_audit(records,scale):\n    result={'measurements':[],'missing':[]}\n    for sid,pixels in records:\n        if pixels is None or scale<=0:\n            result['missing'].append(sid)\n        else:\n            result['measurements'].append([sid,pixels/scale])\n    return result\naudit=build_audit(records,scale)\njson_report=json.dumps(audit,sort_keys=True)\nprint(json_report)","prove":"import json\ndef summarize_input(observations,calibration):\n    valid=[]\n    excluded=[]\n    for pixels,sid in observations:\n        if pixels is None or calibration<=0:\n            excluded.append(sid)\n        else:\n            valid.append(pixels/calibration)\n    return {'n':len(valid),'mean_um':sum(valid)/len(valid) if valid else None,'excluded':excluded}\nresult=summarize_input(observations,calibration)\njson_text=json.dumps(result,sort_keys=True)\nprint(json_text)"},"P06-REVIEW":{"prove":"def reproducible_summary(measures,scale):\n    valid=[]\n    invalid=[]\n    for sid,pixels in measures:\n        if pixels is None or scale<=0:\n            invalid.append(sid)\n        else:\n            valid.append(pixels/scale)\n    return {'count':len(valid),'total_um':sum(valid),'invalid':invalid}\nreport=reproducible_summary(measures,scale)\nprint(f\"count={report['count']}; total_um={report['total_um']}; invalid={len(report['invalid'])}\")"}}''')
TOTAL=0
for cid in ("P04","P05","P06"):
    chapter=json.loads((ROOT/"content"/cid.lower()/"lesson.json").read_text(encoding="utf8"))
    for goal in [*chapter["goals"],chapter["capstone"],chapter["review"]]:
        for phase in ("apply","prove"):
            checks=goal["phases"][phase].get("public_checks",[])
            if not checks:
                assert goal["id"].endswith("-REVIEW") and phase=="apply"
                continue
            code=SOLUTIONS[goal["id"]][phase]
            compile(code, "<author-reference>", "exec")
            for index,case in enumerate(checks):
                given=copy.deepcopy(case["inputs"])
                env={"__name__":"__main__"}
                env.update(copy.deepcopy(given))
                exec(compile(code,"<author-reference>","exec"),env)
                for expression in case["assertions"]:
                    assert bool(eval(compile(expression,"<practice assertion>","eval"),env)),(cid,goal["id"],phase,index,expression)
                for name,value in given.items():
                    assert env[name]==value,(cid,goal["id"],phase,index,"source mutated",name)
                TOTAL+=1
print(f"PASS P04-P06 reference: {TOTAL} changed-input cases; source values preserved")
assert TOTAL==155, TOTAL
